async function diagnostic(){const secure=!!isSecureContext,picker=!!window.showDirectoryPicker;let perm='لا يوجد مجلد';if(libraryHandle)try{perm=await libraryHandle.queryPermission({mode:'read'})}catch{}const e=await navigator.storage?.estimate?.();modal(`<h2>تشخيص OsRa</h2><div class="cards"><div class="card">HTTPS/secure: <b>${secure?'نعم':'لا'}</b></div><div class="card">اختيار المجلد: <b>${picker?'متاح':'غير متاح'}</b></div><div class="card">المجلد: <b>${libraryHandle?esc(libraryHandle.name||'مرتبط'):'غير مرتبط'}</b></div><div class="card">الإذن: <b>${esc(perm)}</b></div><div class="actions"><button class="btn primary" data-action="folder">${libraryHandle?'إعادة منح/تحديث إذن المجلد':'ربط مجلد الصور'}</button>${libraryHandle&&perm!=='granted'?'<button class="btn" data-action="grantPermission">منح الإذن الآن</button>':''}</div><div class="card">الصور المفهرسة: <b>${allPhotos().length}</b></div><div class="card">الذكريات: <b>${state.memories.length}</b></div><div class="card">التخزين المستخدم: <b>${e?.usage?Math.round(e.usage/1024/1024)+' MB':'غير معروف'}</b></div></div>`)}
